      <Tooltip
        label={tree ? 'Every file needs a Drive folder before uploading' : 'Choose a root folder first'}
        disabled={readyToUpload}
      >
        <span>
          <Button size="xs" disabled={!readyToUpload} onClick={handleUploadAll}>
            Upload All
          </Button>
        </span>
      </Tooltip>
    </Toolbar>

